/// <summary>
/// desigend from AVA
/// </summary>
public void modified()
{
    FormDataObject   formDataObject = any2Object(this) as FormDataObject;
    FormDataSource   formDataSource = formDataObject.datasource();
    FormRun          formRun = formDataSource.formRun();
    ProdParmStartUp  prodParmStartUp = formDataSource.cursor(); ;

    next modified();

    formRun.design().controlName('AVASetupButtonProdRunMap').enabled(ProdParmStartUp.AVAPrintProdRunMap);
    formRun.design().controlName('ProdParmStartUp_AVAPrintReferenceRunMap').enabled(prodParmStartUp.AVAPrintProdRunMap);
    if (prodParmStartUp.AVAPrintProdRunMap == NoYes::No)
    {
        prodParmStartUp.AVAPrintReferenceRunMap =  NoYes::No;
    }
}
